$taskFamilies=@('menu.title_panel','menu.background.z1','menu.background.z2','menu.background.z3','menu.old_background_layers','ui.theme_fonts_icons')
[ordered]@{schema_version=1;owner='R3 011';status='Implemented—needs verification; user/Android/final-geography pending';families=$taskFamilies;scene='UI/Menus/Title/TitleMenu.tscn';files=$taskProducts;presentation_sources=$taskSources;reused=$taskReuse;region_count=3;png_products=14;menu_states=19;dialogs=7;source_canvas=@(1672,941);source_tool='Built-in image_gen.imagegen,3calls; exact prompts/native exports retained';title='Original Phase Quest wordmark using retained OFL typeface';selection_owner='R3 021; provider supplies validated active zone, Continue availability, persisted no-repeat choice and final world viewpoint';runtime_boundary='Opt-in menu/dialog intents only; no profile/save/reset/quit/scene/navigation mutation';geography='Staged coherent mainland paintings, not final-world coordinates; no puzzle/discovery spoilers';static_and_layered='Same registered canvas; flattened source plus native editable veil/atmosphere; phase0 pixel agreement checked';retirement_eligible=$false}|ConvertTo-Json -Depth 12|Set-Content -LiteralPath (Join-Path $taskOut catalog.json) -Encoding utf8
