foreach($taskFamily in $taskManifest.families){if($taskFamily.id -notin $taskFamilies){continue};$taskFamily.review_status='R3 011 title/menu/three background sets implemented—needs verification; user/Android/021viewpoint and selection integration pending';$taskFamily.r3_011=[ordered]@{owner='R3 011';catalog='assets/ui/main_menu/r3_v1/catalog.json';coverage='docs/art/r3-prompt011/coverage.json';evidence='docs/art/r3-prompt011/evidence/results.json';consumer='UI/Menus/Title/TitleMenu.tscn';dependencies=@('R3 004/005/006 region identity','R3 010 shared supporting dialogs','R3 021 final viewpoint/selection/input providers');disposition='New opt-in assets; preserve old active menu/background consumers';replacement_dependency='Accepted final021integration and regression before retirement; no deletion here';retirement_eligible=$false}}
